const watchlist = $node['Lire WATCHLIST_BRVM'].json;
const portefeuille = $node['Lire PORTEFEUILLE'].json;

const alertes = [];

// Seuils de détection
const SEUIL_BAISSE_FORTE = -5;        // -5% sur la journée
const SEUIL_BAISSE_OPPORTUNITE = -10; // -10% sur 7 jours = possible opportunité
const SEUIL_HAUSSE_INHABITUELLE = 8;  // +8% sur la journée = surveiller

if (!Array.isArray(watchlist)) return [{ json: { alertes: [] } }];

watchlist.forEach(action => {
  const ticker = action.ticker || action.Ticker;
  const variation_jour = parseFloat(action.variation_jour || 0);
  const variation_7j = parseFloat(action.variation_7j || 0);
  const variation_30j = parseFloat(action.variation_30j || 0);
  const dividende = action.dividende_dernier || action.dividende;
  const note = action.note_analyste || action.statut_agent;

  if (!ticker) return;

  // Signal 1 : Baisse forte du jour (possible point d'entrée pour actions solides)
  if (variation_jour <= SEUIL_BAISSE_FORTE && note !== 'eviter') {
    alertes.push({
      ticker,
      type: 'baisse_forte',
      message: `${ticker} en baisse de ${variation_jour}% aujourd'hui. Note analyste : ${note || 'N/A'}. Analyser si opportunité.`,
      niveau: variation_jour < -8 ? 'élevé' : 'moyen',
      action_recommandee: 'analyser_avant_toute_decision'
    });
  }

  // Signal 2 : Baisse 7j sur action notée intéressante
  if (variation_7j <= SEUIL_BAISSE_OPPORTUNITE && (note === 'interessante' || note === 'achat_progressif_possible')) {
    alertes.push({
      ticker,
      type: 'repli_action_solide',
      message: `${ticker} recule de ${variation_7j}% sur 7 jours mais est notée "${note}". Possible entrée à considérer après analyse approfondie.`,
      niveau: 'moyen',
      action_recommandee: 'analyser_et_attendre_confirmation'
    });
  }

  // Signal 3 : Hausse inhabituelle (surveillance, pas d'action)
  if (variation_jour >= SEUIL_HAUSSE_INHABITUELLE) {
    alertes.push({
      ticker,
      type: 'variation_inhabituelle',
      message: `${ticker} en hausse de +${variation_jour}% aujourd'hui. Variation inhabituelle, surveiller les nouvelles.`,
      niveau: 'faible',
      action_recommandee: 'surveiller_et_ne_pas_suivre_le_mouvement'
    });
  }

  // Signal 4 : Dividende annoncé (si champ rempli récemment)
  if (dividende && parseFloat(dividende) > 0 && action.source_dividende) {
    alertes.push({
      ticker,
      type: 'dividende',
      message: `${ticker} a annoncé un dividende de ${dividende} FCFA/action. Vérifier date de détachement.`,
      niveau: 'faible',
      action_recommandee: 'verifier_details_et_date_detachement'
    });
  }

  // Signal 5 : Action en portefeuille avec baisse > 15%
  if (Array.isArray(portefeuille)) {
    const positionExistante = portefeuille.find(p => (p.ticker || p.Ticker) === ticker);
    if (positionExistante) {
      const gainPct = parseFloat(positionExistante.gain_perte_pct || 0);
      if (gainPct <= -15) {
        alertes.push({
          ticker,
          type: 'position_en_perte',
          message: `ATTENTION : Votre position ${ticker} est en perte de ${gainPct}%. Revoir la thèse d'investissement.`,
          niveau: 'élevé',
          action_recommandee: 'revoir_these_investissement_ne_pas_paniquer'
        });
      }
    }
  }
});

return [{ json: { alertes, nb_alertes: alertes.length } }];

