const reponse = $input.first().json.text || $input.first().json.content || '';

let data;
try {
  const jsonMatch = reponse.match(/\{[\s\S]*\}/);
  data = jsonMatch ? JSON.parse(jsonMatch[0]) : { alertes_validees: [], message_global: reponse };
} catch(e) {
  data = { alertes_validees: [], message_global: reponse };
}

return [{ json: data }];

// Préparer les lignes à insérer dans ALERTES
const alertes = $input.first().json.alertes_validees || [];
return alertes.map(a => ({
  json: {
    date: new Date().toISOString(),
    type_alerte: a.type,
    ticker: a.ticker,
    message: a.message_telegram,
    niveau_risque: a.niveau,
    action_recommandee: a.mise_en_garde || 'analyser avant toute décision',
    statut: 'nouvelle',
    source: 'Agent Risque n8n'
  }
}));

const data = $input.first().json;
const alertes = data.alertes_validees || [];

if (alertes.length === 0) {
  return [{ json: { message: null } }];
}

const niveauEmoji = { 'faible': '🟡', 'moyen': '🟠', 'élevé': '🔴' };

const alertesTexte = alertes.slice(0, 5).map(a => {
  const emoji = niveauEmoji[a.niveau] || '⚪';
  return `${emoji} *${a.ticker}* — ${a.type}\n_${a.message_telegram}_\n⚠️ ${a.mise_en_garde}`;
}).join('\n\n');

const message = `🚨 *Signaux détectés — BRVM*
_${new Date().toLocaleDateString('fr-FR')}_

${alertesTexte}

─────────────────
🛑 *RAPPEL IMPORTANT :*
Ces signaux nécessitent une analyse approfondie avant toute décision.
• Aucun achat ne doit être fait sur la base de ces alertes seules.
• Consultez votre JOURNAL_DECISIONS avant d'agir.
• En cas de doute : attendre.

💡 _Investisseur Afrique BRVM_`;

return [{ json: { message } }];
